equation_logic_text:
var calc_output=[]; 

var u=parseInt(age)+parseInt(sex)+parseInt(cancer)+parseInt(heart_failure)+parseInt(chronic_lung_disease)+parseInt(heart_rate_110)+parseInt(systolic_blood_pressure_100)+parseInt(respiratory_rate_30)+parseInt(temperature_36)+parseInt(altered_mental_status)+parseInt(o2_saturation_90);

var msg='';
var mini_msg=''; 

if(u<66){
    msg='Class I <br> Very low risk.';
    mini_msg='Very Low Risk.'
} 
if(u>65&&u<86){
    msg='Class II <br> Low risk.';
    mini_msg='Low Risk.'
} 
if(u>85&&u<106){
    msg='Class III <br> Intermediate risk.';
    mini_msg='Intermediate Risk.'
} 
if(u>105&&u<126){
    msg='Class IV <br> High risk.';
    mini_msg='High Risk.'
} 
if(u>125){
    msg='Class V <br> Very high risk.';
    mini_msg='Very High Risk.'
} 

calc_output.push({
    name:'mini',
    value:u,
    value_text:'points',
    message:mini_msg
}); 
calc_output.push({
    name:'1304_PESI Score_result',
    value:u,
    value_text:'points',
message:msg
});
